        std::vector<int> out;
        if (count_ == 0) return out;
        const std::size_t first = count_ == slots_.size() ? next_ : 0;
        for (std::size_t i = 0; i < count_; ++i) out.push_back(slots_[(first + i) % slots_.size()].value);
