    std::size_t next = 0;
    for (long long target : pattern) {
        while (next < host.size() && !within_tolerance(host[next], target, tolerance)) ++next;
        if (next == host.size()) return std::nullopt;
        indices.push_back(++next);
    }
    return indices;
}
